+// Measure VRAM consumed by the configured speculative draft model.
+// Uses the real initialization path (same as runtime) so the result is exact.
+speculative_vram_measurement common_speculative_measure_vram(const common_params & params) {
+    speculative_vram_measurement result;
+
+    // 1. Check if a draft model is configured.
+    if (!params.speculative.has_dft()) {
+        result.error = "No speculative draft model configured";
+        return result;
+    }
+
+    // 2. Build draft params using the same transformation as real runtime.
+    common_params draft_params = common_base_params_to_speculative(params);
+
+    // 3. Get draft device list.
+    auto & devices = draft_params.devices;
+    if (devices.empty()) {
+        result.error = "Draft model has no devices configured";
+        return result;
+    }
+
+    // 4. Query baseline VRAM per device.
+    std::map<std::string, size_t> free_before;
+    for (auto dev : devices) {
+        size_t free_mem = 0, total = 0;
+        ggml_backend_dev_memory(dev, &free_mem, &total);
+        free_before[ggml_backend_dev_name(dev)] = free_mem;
+    }
+
+    // 5. Load draft model + context using the real init path.
+    auto mparams = common_model_params_to_llama(draft_params);
+    auto cparams = common_context_params_to_llama(draft_params);
+
+    llama_model * model_dft = llama_model_load_from_file(
+        draft_params.model.path.c_str(), mparams);
+    if (!model_dft) {
+        result.error = "Failed to load draft model for measurement";
+        return result;
+    }
+
+    llama_context * ctx_dft = llama_init_from_model(model_dft, cparams);
+    if (!ctx_dft) {
+        llama_model_free(model_dft);
+        result.error = "Failed to create draft context for measurement";
+        return result;
+    }
+
+    // 6. Query post-allocation VRAM per device and compute delta.
+    int64_t total_delta = 0;
+    for (auto dev : devices) {
+        const char * name = ggml_backend_dev_name(dev);
+        size_t free_after = 0, total = 0;
+        ggml_backend_dev_memory(dev, &free_after, &total);
+        int64_t delta = static_cast<int64_t>(free_before[name]) - static_cast<int64_t>(free_after);
+        result.per_device_vram[name] = delta;
+        total_delta += delta;
+    }
+    result.total_vram = total_delta;
+    result.valid = true;
+
+    // 7. Cleanup (RAII handles destruction order).
+    llama_free(ctx_dft);
+    llama_model_free(model_dft);
+
+    return result;
+}
